class Solution {
  public long minCost(int m, int n, int[][] penalty) {
    long INF = Long.MAX_VALUE / 4;
    long[] dist = new long[m * n * 2];
    java.util.Arrays.fill(dist, INF);
    java.util.PriorityQueue<long[]> pq =
        new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
    dist[0] = 1;
    pq.add(new long[] {1, 0});
    int[] dx = {1, 0, -1, 0}, dy = {0, 1, 0, -1};
    while (!pq.isEmpty()) {
      long[] top = pq.poll();
      int state = (int) top[1];
      if (top[0] > dist[state]) continue;
      int parity = state & 1, cell = state >> 1, i = cell / n, j = cell % n;
      if (i == m - 1 && j == n - 1) return top[0];
      int np = parity ^ 1;
      // wait
      long wait = top[0] + penalty[i][j];
      int ws = (cell << 1) | np;
      if (wait < dist[ws]) {
        dist[ws] = wait;
        pq.add(new long[] {wait, ws});
      }
      for (int d = 0; d < 4; d++) {
        int x = i + dx[d], y = j + dy[d];
        if (x < 0 || y < 0 || x >= m || y >= n) continue;
        boolean forward = d < 2; // right/down
        boolean follows = parity == 0 ? forward : !forward; // parity 0: next action is odd-numbered
        long c = top[0] + (long) (x + 1) * (y + 1) + (follows ? 0 : penalty[i][j]);
        int ns = ((x * n + y) << 1) | np;
        if (c < dist[ns]) {
          dist[ns] = c;
          pq.add(new long[] {c, ns});
        }
      }
    }
    return -1;
  }
}
